// Pick one trend from today's feed that has not been posted yet, and build the
// caption from the feed's own words. Nothing here is written by a model: the
// search term, the headline and the outlet name all come from Google, so there
// is no step at which a fact can be invented.
//
// Returning [] is a normal outcome. It means every trend today was either
// already posted, had no article attached, or read as grief or crime.

// Grief, crime and disaster words. A page that earns from reach still has to
// be a page someone wants to follow, and "it is trending" is not a reason to
// post a death notice between two cricket updates.
const SENSITIVE = [
  'died', 'dies', 'death', 'dead', 'killed', 'kill', 'murder', 'shot', 'shooting',
  'rape', 'raped', 'assault', 'suicide', 'crash', 'crashed', 'earthquake', 'quake',
  'flood', 'landslide', 'accident', 'arrest', 'arrested', 'jailed', 'scandal',
  'bomb', 'bombing', 'terror', 'obituary', 'funeral', 'missing', 'injured',
  'hospitalised', 'hospitalized', 'fraud', 'scam', 'corruption', 'outbreak',
  'cancer', 'massacre', 'stabbed', 'abuse', 'overdose', 'collapse',
];

function decode(s) {
  return s
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
    .trim();
}

function parseTrends(xml) {
  const items = [];
  for (const block of xml.split('<item>').slice(1)) {
    const body = block.split('</item>')[0];
    const pick = (tag) => {
      const m = body.match(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>`));
      return m ? decode(m[1]) : '';
    };
    const term = pick('title');
    if (!term) continue;

    const news = [];
    for (const n of body.split('<ht:news_item>').slice(1)) {
      const nb = n.split('</ht:news_item>')[0];
      const g = (tag) => {
        const m = nb.match(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>`));
        return m ? decode(m[1]) : '';
      };
      const url = g('ht:news_item_url');
      const headline = g('ht:news_item_title');
      if (url && headline) news.push({ headline, url, source: g('ht:news_item_source') });
    }

    items.push({
      term,
      traffic: pick('ht:approx_traffic'),
      picture: pick('ht:picture'),
      pubDate: pick('pubDate'),
      news,
    });
  }
  return items;
}

// Only the term and the lead headline are screened, because only those two go
// into the post. Screening the secondary headlines as well rejected an anime
// finale for the words "Thousand-Year Blood War" and a markets story for
// "Trade War Rout", neither of which would have appeared in the caption.
function isSensitive(trend, extraWords) {
  const words = SENSITIVE.concat(extraWords || []).filter(Boolean);
  const hay = [trend.term, trend.news[0] ? trend.news[0].headline : '']
    .join(' ')
    .toLowerCase();
  return words.find((w) => new RegExp(`\\b${w}\\b`, 'i').test(hay)) || null;
}

// The search term is quoted rather than dropped into the sentence as a name.
// Google Trends reports terms lowercase ("ipl", "nepse"), and title-casing
// them guesses wrong in both directions: "Ipl" and "Fc Bayern Munich". Quoted,
// it is accurate, because a search phrase is exactly what it is.
function caption(trend, opts) {
  const place = (opts && opts.place) || 'Nepal';
  const lead = trend.news[0];
  const out = [];
  const volume = trend.traffic ? `, around ${trend.traffic} searches so far` : '';
  out.push(`People in ${place} are searching for "${trend.term}" today${volume}.`);
  out.push('');
  out.push(`${lead.headline}${lead.source ? ` (${lead.source})` : ''}`);
  const others = trend.news.slice(1).map((n) => n.source).filter(Boolean);
  if (others.length) out.push(`Also reported by ${others.slice(0, 2).join(' and ')}.`);
  return { message: out.join('\n'), link: lead.url, source: lead.source || '' };
}



const xml = String($json.data ?? $json.body ?? '');
if (!xml.includes('<item>')) {
  throw new Error(`Google Trends returned nothing that looks like the feed (${xml.length} characters). Nothing was posted.`);
}

const place = $env.TRENDS_PLACE || 'Nepal';
const extra = String($env.TRENDS_BLOCKLIST || '')
  .split(',')
  .map((w) => w.trim().toLowerCase())
  .filter(Boolean);

// A term is not offered again for this many days. Without it the same story
// goes out every run for as long as it keeps trending.
const COOLDOWN_DAYS = Number($env.TRENDS_COOLDOWN_DAYS || 14);
const store = $getWorkflowStaticData('global');
store.posted = Array.isArray(store.posted) ? store.posted : [];
const cutoff = Date.now() - COOLDOWN_DAYS * 86400000;
store.posted = store.posted.filter((p) => p && p.at > cutoff);
const alreadyPosted = new Set(store.posted.map((p) => String(p.term).toLowerCase()));

const trends = parseTrends(xml);
const skipped = [];
const usable = [];

for (const t of trends) {
  if (!t.news.length) {
    skipped.push(`${t.term}: no article attached`);
    continue;
  }
  if (alreadyPosted.has(t.term.toLowerCase())) {
    skipped.push(`${t.term}: posted in the last ${COOLDOWN_DAYS} days`);
    continue;
  }
  const word = isSensitive(t, extra);
  if (word) {
    skipped.push(`${t.term}: reads as grief or crime ("${word}")`);
    continue;
  }
  usable.push(t);
}

if (!usable.length) {
  console.log(`Nothing to post. ${trends.length} trends examined:\n  ${skipped.join('\n  ')}`);
  return [];
}

// Picked at random rather than by volume, so the page does not post the same
// top story shape every day.
const chosen = usable[Math.floor(Math.random() * usable.length)];
const built = caption(chosen, { place });

return [
  {
    json: {
      origin: 'trends',
      term: chosen.term,
      message: built.message,
      link: built.link,
      source: built.source,
      considered: usable.length,
      skipped,
    },
  },
];

// The gate in front of the webhook.
//
// Anything holding the shared secret can publish to the Page through here, so
// this node is the only thing between a loose URL and the Page's wall. It
// fails closed: no secret configured on the service means every call is
// refused, rather than the webhook quietly accepting unsigned ones.
const secret = String($env.MUSE_WEBHOOK_SECRET || '');
if (!secret) {
  throw new Error(
    'MUSE_WEBHOOK_SECRET is not set on the n8n service, so this webhook refuses every call. Set it in Coolify and redeploy.',
  );
}

const headers = $json.headers || {};
const given = String(headers['x-muse-secret'] || headers['x-webhook-secret'] || '');
// Constant-time-ish: compare full length, never short-circuit on first byte.
const same =
  given.length === secret.length &&
  given.split('').reduce((acc, c, i) => acc + (c === secret[i] ? 0 : 1), 0) === 0;
if (!same) {
  throw new Error('Refused: the x-muse-secret header was missing or did not match.');
}

const body = $json.body || {};
const message = String(body.message ?? body.text ?? body.caption ?? '').trim();
if (!message) {
  throw new Error('Refused: the body had no "message". Send {"message": "...", "link": "https://..."}.');
}
// Facebook's own limit on a feed post.
if (message.length > 63206) {
  throw new Error(`Refused: the message is ${message.length} characters and Facebook accepts 63206.`);
}

const link = String(body.link ?? body.url ?? '').trim();
if (link && !/^https:\/\/[^\s]+$/.test(link)) {
  throw new Error(`Refused: "link" must be a single https URL, got "${link.slice(0, 80)}".`);
}

return [
  {
    json: {
      origin: 'muse',
      term: String(body.term ?? body.topic ?? '').trim() || '(sent by Muse)',
      message,
      link,
      source: String(body.source ?? '').trim(),
    },
  },
];

// Facebook answers 200 with an error object in the body, so the status code on
// its own is not proof that anything was published. The post counts as landed
// only when a post id comes back.
//
// The term is recorded as posted here and nowhere earlier: marking it before
// the Page confirmed would silently drop a trend on every failed run.
const res = $json || {};
const body = res.body || {};
const status = Number(res.statusCode || 0);
const postId = body.id ? String(body.id) : '';
const landed = status >= 200 && status < 300 && !!postId && !body.error;

// Whichever branch ran. Calling $() on a node that did not execute throws.
let src = null;
for (const name of ['Pick a trend nobody has posted', 'Check what Muse sent']) {
  try {
    const j = $(name).first().json;
    if (j && j.message) {
      src = j;
      break;
    }
  } catch (e) {
    /* that branch did not run */
  }
}
src = src || { origin: 'unknown', term: '(unknown)', message: '', link: '' };

if (landed && src.origin === 'trends') {
  const store = $getWorkflowStaticData('global');
  store.posted = Array.isArray(store.posted) ? store.posted : [];
  store.posted.push({ term: src.term, at: Date.now() });
  // Keep the file small; the cooldown filter prunes by date on the way in.
  if (store.posted.length > 400) store.posted = store.posted.slice(-400);
}

const reason = landed
  ? ''
  : body.error
    ? `Facebook refused it: ${body.error.message || JSON.stringify(body.error)}`
    : `Facebook answered ${status || 'nothing'} with no post id. Body: ${JSON.stringify(body).slice(0, 400)}`;

return [
  {
    json: {
      landed,
      failed: !landed,
      origin: src.origin,
      term: src.term,
      postId,
      permalink: postId ? `https://www.facebook.com/${postId}` : '',
      link: src.link || '',
      message: src.message,
      reason,
    },
  },
];

